// Renders every raster icon AdVault ships, from the favicon artwork
// (web/src/app/icon.svg: an amber "A" on a near-black tile):
//
//   web/public/icons/icon-{192,512}.png       PWA "any" icons (rounded tile, as the favicon)
//   web/public/icons/maskable-{192,512}.png   PWA maskable icons (full bleed, art in the safe zone)
//   infra/play-store/graphics/icon-512.png    Play hi-res icon (full bleed, opaque; Play masks it)
//   infra/play-store/graphics/feature-graphic.png  1024 x 500 Play feature graphic
//
// The Android launcher icons in android/ are generated by Bubblewrap from the
// 512 PWA icons, so rerun this, redeploy the web app, and regenerate android/
// if the artwork changes.
//
//   cd infra/play-store/tools && npm install && npm run graphics
import { chromium } from "playwright";
import { mkdirSync } from "node:fs";
import { fileURLToPath } from "node:url";

const here = (p) => fileURLToPath(new URL(p, import.meta.url));
const WEB_ICONS = here("../../../web/public/icons/");
const PLAY = here("../graphics/");
mkdirSync(WEB_ICONS, { recursive: true });
mkdirSync(PLAY, { recursive: true });

const BG = "#09090b";
const AMBER = "#f5c242";

// Same strokes as icon.svg (viewBox 32). `rx` rounds the tile; `scale`
// shrinks the "A" toward the centre so it survives a circular mask
// (maskable safe zone = 80% diameter circle).
function icon({ rx, scale }) {
  const off = (32 * (1 - scale)) / 2;
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 32 32">
  <rect width="32" height="32" rx="${rx}" fill="${BG}"/>
  <g transform="translate(${off} ${off}) scale(${scale})">
    <path d="M9 23 L16 8 L23 23" stroke="${AMBER}" stroke-width="3" fill="none" stroke-linecap="round" stroke-linejoin="round"/>
    <path d="M12.5 18 H19.5" stroke="${AMBER}" stroke-width="3" stroke-linecap="round"/>
  </g>
</svg>`;
}

const TILE = icon({ rx: 7, scale: 1 });
const MASKABLE = icon({ rx: 0, scale: 0.8 });
const PLAY_ICON = icon({ rx: 0, scale: 0.95 });

const page = (size, svg) => `<!doctype html><html><head><style>html,body{margin:0;background:transparent}
  svg{display:block;width:${size}px;height:${size}px}</style></head><body>${svg}</body></html>`;

const FEATURE = `<!doctype html><html><head>
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@500;700;800&display=swap" rel="stylesheet">
<style>
  html,body{margin:0}
  .f{width:1024px;height:500px;position:relative;overflow:hidden;font-family:Inter,sans-serif;
     background:radial-gradient(60% 80% at 0% 0%, rgba(245,194,66,.22) 0%, transparent 70%),
                radial-gradient(55% 75% at 100% 100%, rgba(244,114,182,.16) 0%, transparent 70%),${BG};
     display:flex;align-items:center;gap:56px;padding:0 72px;box-sizing:border-box}
  .icon{flex:none;width:240px;height:240px;filter:drop-shadow(0 24px 40px rgba(245,194,66,.25))}
  .icon svg{width:240px;height:240px}
  h1{margin:0;font-size:84px;font-weight:800;letter-spacing:-2px;color:#fafafa}
  p{margin:14px 0 0;font-size:34px;font-weight:500;line-height:1.25;color:#d4d4d8}
  p b{color:${AMBER};font-weight:700}
  small{display:block;margin-top:22px;font:500 20px/1 ui-monospace,Menlo,Consolas,monospace;letter-spacing:3px;color:#71717a}
</style></head><body><div class="f">
  <div class="icon">${TILE}</div>
  <div><h1>AdVault</h1><p>Your local business on YouTube.<br><b>Made from your own photos.</b></p><small>BY 3PANDALABS</small></div>
</div></body></html>`;

const jobs = [
  { out: WEB_ICONS + "icon-192.png", size: 192, html: page(192, TILE) },
  { out: WEB_ICONS + "icon-512.png", size: 512, html: page(512, TILE) },
  { out: WEB_ICONS + "maskable-192.png", size: 192, html: page(192, MASKABLE) },
  { out: WEB_ICONS + "maskable-512.png", size: 512, html: page(512, MASKABLE) },
  // Play rejects alpha; Play rounds the corners itself.
  { out: PLAY + "icon-512.png", size: 512, html: page(512, PLAY_ICON), opaque: true },
  { out: PLAY + "feature-graphic.png", w: 1024, h: 500, html: FEATURE, opaque: true },
];

// android/ resources, at the sizes Bubblewrap generates them (mdpi→xxxhdpi),
// so the project never needs a `bubblewrap update` just for artwork.
const RES = here("../../../android/app/src/main/res/");
const DENSITIES = { mdpi: 1, hdpi: 1.5, xhdpi: 2, xxhdpi: 3, xxxhdpi: 4 };
for (const [d, k] of Object.entries(DENSITIES)) {
  mkdirSync(`${RES}mipmap-${d}`, { recursive: true });
  mkdirSync(`${RES}drawable-${d}`, { recursive: true });
  jobs.push(
    { out: `${RES}mipmap-${d}/ic_launcher.png`, size: 48 * k, html: page(48 * k, TILE) },
    { out: `${RES}mipmap-${d}/ic_maskable.png`, size: Math.round(82 * k), html: page(Math.round(82 * k), MASKABLE) },
    { out: `${RES}drawable-${d}/splash.png`, size: 300 * k, html: page(300 * k, TILE) },
    { out: `${RES}drawable-${d}/shortcut_0.png`, size: 48 * k, html: page(48 * k, TILE) },
  );
}
jobs.push({ out: here("../../../android/store_icon.png"), size: 512, html: page(512, PLAY_ICON), opaque: true });

const browser = await chromium.launch();
for (const j of jobs) {
  const w = j.w ?? j.size;
  const h = j.h ?? j.size;
  const p = await browser.newPage({ viewport: { width: w, height: h }, deviceScaleFactor: 1 });
  await p.setContent(j.html, { waitUntil: "networkidle" });
  await p.evaluate(() => document.fonts.ready);
  await p.screenshot({ path: j.out, omitBackground: !j.opaque, clip: { x: 0, y: 0, width: w, height: h } });
  await p.close();
  console.log(`${w}x${h}  ${j.out}`);
}
await browser.close();
